Bash(powershell -Command "
\\$BASE = 'C:\\Users\\user\\OneDrive\\Desktop\\Nanopore-project\\AccuracyDrift\\runs\\fbe_pod5_hac'
\\$ESKAPE = @\('Enterococcus faecium','Staphylococcus aureus','Klebsiella pneumoniae','Acinetobacter baumannii','Pseudomonas aeruginosa','Enterobacter cloacae'\)

function Parse-Report\(\\$path\) {
    \\$total = 0; \\$unc = 0; \\$sp = @{}
    foreach \(\\$line in [System.IO.File]::ReadLines\(\\$path\)\) {
        \\$p = \\$line.Split\('\\`t'\)
        if \(\\$p.Count -lt 6\) { continue }
        \\$count = [int]\\$p[1]; \\$rank = \\$p[3].Trim\(\); \\$name = \\$p[5].Trim\(\)
        if \(\\$rank -eq 'U'\) { \\$unc = \\$count }
        elseif \(\\$rank -eq 'R' -and \(\\$name -eq 'root' -or \\$name -eq ''\)\) { \\$total = \\$count + \\$unc }
        elseif \(\\$rank -eq 'S' -and \\$ESKAPE -contains \\$name\) { \\$sp[\\$name] = \\$count }
    }
    return \\$total, \\$unc, \\$sp
}

for \(\\$i = 0; \\$i -le 15; \\$i++\) {
    \\$sf = Join-Path \\$BASE \\"\\$i\\sample_targeted\\report.txt\\"
    \\$lf = Join-Path \\$BASE \\"\\$i\\pluspf_103gb\\report.txt\\"
    \\$st, \\$su, \\$ss = Parse-Report \\$sf
    \\$lt, \\$lu, \\$ls = Parse-Report \\$lf
    \\$sEsk = 0; \\$lEsk = 0
    foreach \(\\$s in \\$ESKAPE\) { \\$sEsk += if \(\\$ss[\\$s]\) { \\$ss[\\$s] } else { 0 }; \\$lEsk += if \(\\$ls[\\$s]\) { \\$ls[\\$s] } else { 0 } }
    \\$sOth = \\$st - \\$su - \\$sEsk; \\$lOth = \\$lt - \\$lu - \\$lEsk
    Write-Host \\"POD5=\\$i ST=\\$st SU=\\$su LT=\\$lt LU=\\$lu SOTH=\\$sOth LOTH=\\$lOth\\"
    foreach \(\\$s in \\$ESKAPE\) {
        \\$sc = if \(\\$ss[\\$s]\) { \\$ss[\\$s] } else { 0 }
        \\$lc = if \(\\$ls[\\$s]\) { \\$ls[\\$s] } else { 0 }
        Write-Host \\"  \\$s | S=\\$sc L=\\$lc\\"
    }
}
")
